package dev.veltraph.client.mining.vein;
import dev.veltraph.client.world.BlockPos;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class VeinIncompleteGeometryTest {
 final Object p=new Object(),w=new Object(),c=new Object(),o=new Object(),cam=new Object();final VeinBreakSession.Scope scope=new VeinBreakSession.Scope(p,w,c,o,cam,"cfg","tool",0,1);
 VeinBreakSession.Frame frame(boolean geometry,boolean ray,long at){return new VeinBreakSession.Frame(scope,new BlockPos(1,71,1),"minecraft:gray_wool",geometry,geometry,ray,true,true,geometry,true,true,false,0,at);}
 VeinBreakSession admitted(){var s=new VeinBreakSession();assertTrue(s.begin(frame(true,false,1000),1000,1000));return s;}
 @Test void actualPartialAimFrameDoesNotPoisonNextCompleteAction(){var s=admitted();assertEquals(VeinBreakSession.State.AIMING,s.tickGeometry(frame(false,false,1051),1051,false));assertFalse(s.attackRequested());assertEquals(VeinBreakSession.State.BREAKING,s.tickGeometry(frame(true,true,1102),1102,true));assertTrue(s.attackRequested());}
 @Test void partialActionRevokesAttackWithoutGrantingPartialProof(){var s=admitted();s.tickGeometry(frame(true,true,1050),1050,true);assertEquals(VeinBreakSession.State.BREAKING,s.tickGeometry(frame(false,true,1100),1100,false));assertFalse(s.attackRequested());assertFalse(s.permits(new BlockPos(1,71,1),frame(true,true,1100),1100));}
 @Test void repeatedIncompleteFramesCannotExtendDeadline(){var s=admitted();for(int now=1050;now<2000;now+=50)s.tickGeometry(frame(false,false,now),now,false);assertEquals(VeinBreakSession.State.TIMED_OUT,s.tickGeometry(frame(false,false,2000),2000,false));assertFalse(s.attackRequested());}
 @Test void rollbackStillStopsWhileIncomplete(){var s=admitted();s.tickGeometry(frame(true,false,1100),1100,true);assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(false,false,1050),1050,false));}
 @Test void completeUnsafeFrameStillStops(){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(false,true,1050),1050,true));}
 @Test void completeStaleFrameRemainsDenied(){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1000),1251,true));}
 @Test void rollbackBetweenTwoIncompleteSamplesStillStops(){var s=admitted();s.tickGeometry(frame(false,false,1100),1100,false);assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(false,false,1050),1050,false));}
 VeinBreakSession.Frame partial(VeinBreakSession.Scope scope,BlockPos cell,boolean tool,boolean capacity,boolean screen,boolean quiet,long observed,long serial){return new VeinBreakSession.Frame(scope,cell,"minecraft:gray_wool",false,false,false,tool,capacity,false,screen,quiet,false,serial,observed);}
 @Test void partialGeometryCannotHideIndependentKnownRevocations(){for(int flag=0;flag<4;flag++){var s=admitted();var f=partial(scope,new BlockPos(1,71,1),flag!=0,flag!=1,flag!=2,flag!=3,1050,0);assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(f,1050,false));assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1100),1100,true));assertFalse(s.attackRequested());}}
 @Test void partialGeometryCannotHideScopeSlotConfigToolActivationOrOwnerChanges(){var changed=java.util.List.of(new VeinBreakSession.Scope(p,w,c,new Object(),cam,"cfg","tool",0,1),new VeinBreakSession.Scope(p,w,c,o,new Object(),"cfg","tool",0,1),new VeinBreakSession.Scope(p,w,c,o,cam,"other-cfg","tool",0,1),new VeinBreakSession.Scope(p,w,c,o,cam,"cfg","other-tool",0,1),new VeinBreakSession.Scope(p,w,c,o,cam,"cfg","tool",1,1),new VeinBreakSession.Scope(p,w,c,o,cam,"cfg","tool",0,2),new VeinBreakSession.Scope(new Object(),w,c,o,cam,"cfg","tool",0,1),new VeinBreakSession.Scope(p,new Object(),c,o,cam,"cfg","tool",0,1),new VeinBreakSession.Scope(p,w,new Object(),o,cam,"cfg","tool",0,1));for(var foreign:changed){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(partial(foreign,new BlockPos(1,71,1),true,true,true,true,1050,0),1050,false));assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1100),1100,true));}}
 @Test void partialGeometryCannotHideChangedCell(){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(partial(scope,new BlockPos(2,71,1),true,true,true,true,1050,0),1050,false));}
 @Test void partialGeometryStaleFutureOrNegativeReceiptIsTerminal(){for(var f:java.util.List.of(partial(scope,new BlockPos(1,71,1),true,true,true,true,1000,0),partial(scope,new BlockPos(1,71,1),true,true,true,true,1252,0),partial(scope,new BlockPos(1,71,1),true,true,true,true,1251,-1))){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(f,1251,false));assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1300),1300,true));}}
 VeinBreakSession.Frame stateFrame(String state,boolean receipt,long serial,long time){return new VeinBreakSession.Frame(scope,new BlockPos(1,71,1),state,false,false,false,true,true,false,true,true,receipt,serial,time);}
 @Test void knownPartialReplacementCannotRestoreOldBlockAndAttack(){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(stateFrame("minecraft:stone",false,0,1050),1050,false));assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1100),1100,true));assertFalse(s.attackRequested());}
 @Test void partialAirBeforeIssuedAttackIsTerminal(){var s=admitted();assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(stateFrame("minecraft:air",false,1,1050),1050,false));assertFalse(s.attackRequested());}
 @Test void partialPredictedAirAfterIssueWaitsButRestoredOriginalCannotAttack(){var s=admitted();s.tickGeometry(frame(true,true,1050),1050,true);assertEquals(VeinBreakSession.State.WAITING_RECEIPT,s.tickGeometry(stateFrame("minecraft:air",false,1,1100),1100,false));assertFalse(s.attackRequested());assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1150),1150,true));assertFalse(s.attackRequested());}
 @Test void partialAuthenticAirCannotCreditUntilFreshCompleteGeometry(){var s=admitted();s.tickGeometry(frame(true,true,1050),1050,true);assertEquals(VeinBreakSession.State.WAITING_RECEIPT,s.tickGeometry(stateFrame("minecraft:air",true,1,1100),1100,false));var complete=new VeinBreakSession.Frame(scope,new BlockPos(1,71,1),"minecraft:air",true,true,false,true,true,true,true,true,true,1,1150);assertEquals(VeinBreakSession.State.REMOVED,s.tickGeometry(complete,1150,true));assertFalse(s.attackRequested());}
 @Test void pendingPartialAirRetainsOriginalDeadline(){var s=admitted();s.tickGeometry(frame(true,true,1050),1050,true);s.tickGeometry(stateFrame("minecraft:air",false,1,1100),1100,false);assertEquals(VeinBreakSession.State.TIMED_OUT,s.tickGeometry(stateFrame("minecraft:air",true,1,2000),2000,false));}
 @Test void fullPredictedAirAlsoLatchesAgainstStateRestore(){var s=admitted();s.tickGeometry(frame(true,true,1050),1050,true);var air=new VeinBreakSession.Frame(scope,new BlockPos(1,71,1),"minecraft:air",true,true,false,true,true,true,true,true,false,1,1100);assertEquals(VeinBreakSession.State.WAITING_RECEIPT,s.tickGeometry(air,1100,true));assertEquals(VeinBreakSession.State.STOPPED,s.tickGeometry(frame(true,true,1150),1150,true));}
}
